CREATE TABLE IF NOT EXISTS accounts(id VARCHAR(64) PRIMARY KEY,username VARCHAR(64) NOT NULL UNIQUE,password VARCHAR(100) NOT NULL,role VARCHAR(16) NOT NULL,balance BIGINT NOT NULL CHECK(balance>=0));
CREATE TABLE IF NOT EXISTS wallet_ledger(operation_id VARCHAR(100) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,delta BIGINT NOT NULL,kind VARCHAR(20) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS addresses(id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,recipient VARCHAR(64),phone VARCHAR(32),detail VARCHAR(500));